"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[71414],{50421:e=>{e.exports=JSON.parse('{"functions":[{"name":"Wire","desc":"Wires the hold events of the prompt under `model`\'s `promptPartName` part.\\nDestroy the returned Janitor to unwire (it also removes the attribute).","params":[{"name":"model","desc":"","lua_type":"Instance"},{"name":"promptPartName","desc":"","lua_type":"string"},{"name":"attr","desc":"","lua_type":"string"},{"name":"canHold","desc":"","lua_type":"(Player) -> boolean"},{"name":"tolerance","desc":"","lua_type":"number\\n"}],"returns":[{"desc":"nil when the prompt part or its prompt is missing.","lua_type":"Janitor?"}],"function_type":"static","source":{"line":89,"path":"src/ServerStorage/SharedModules/PromptHoldTracker.luau"}}],"properties":[],"types":[],"name":"PromptHoldTracker","desc":"Publishes who is holding a ProximityPrompt as a UserId number attribute on a\\nstation model (0 = nobody). Hold events replicate to the server natively, but\\nRoblox runs no distance check on them (only Triggered has one), so each hold\\nstart is checked with `ProximityValidation.IsPlayerNear` plus the caller\'s own\\n`canHold`. A watchdog drops a hold whose end event never came (death,\\nteleport, faked hold) after `HoldDuration + TrainConfig.REFUEL_HOLD_GRACE`.\\nThe attribute is cosmetic only: the real action stays on `Triggered`.\\nUsed by `TrainFuelManager` (engine, `RefuelingBy`) and `JumpDriveManager`\\n(energy chute, `ChargingBy`).","source":{"line":15,"path":"src/ServerStorage/SharedModules/PromptHoldTracker.luau"}}')}}]);